-- Migration 030: Seed the complete Terms of Service / Privacy Policy /
-- Conditions of Use into school_settings (single row id = 1) so the login
-- consent modals AND the School Settings editor show the full text.
-- Format: JSON { intro, sections: [{ heading, body }] } (mirrors Login.tsx).

UPDATE school_settings
SET terms_of_service_text = '{"intro":"The Hi5 Portal is the Student Information System of Don Servillano Platon Memorial National High School (DSPMNHS). By accessing and using the portal you accept these Terms of Service, together with the Privacy Policy and Conditions of Use.","sections":[{"heading":"1. Authorized Use","body":"The Hi5 Portal is intended solely for authorized school personnel of DSPMNHS. Accounts are issued individually and must not be shared. Unauthorized access or use is prohibited and may result in disciplinary and legal action."},{"heading":"2. Account Responsibility","body":"You are responsible for all activity performed under your account. Keep your password confidential and notify the ICT Coordinator immediately if you suspect unauthorized use."},{"heading":"3. Purpose of the System","body":"The system is provided to manage enrollment, academic records, grade encoding, class schedules, school form generation (SF1, SF5, SF9, SF10), and reporting to the Department of Education (DepEd)."},{"heading":"4. Acceptable Use","body":"Use the system only for legitimate school operations. Attempting to access data outside your assigned role, tampering with records, or extracting personal data for personal use is strictly prohibited."},{"heading":"5. Monitoring and Logging","body":"All significant actions performed in the portal are logged with the user, timestamp, and relevant record for accountability and security purposes. By using the system you consent to this monitoring."},{"heading":"6. Availability","body":"While the school strives for continuous availability, the system may be temporarily unavailable due to maintenance, scheduled backups, or events beyond the school''s control."},{"heading":"7. Changes to Terms","body":"DSPMNHS may update these Terms from time to time. Continued use after changes are posted constitutes acceptance of the revised Terms."}]}',
    privacy_policy_text = '{"intro":"The Hi5 Portal processes personal data in compliance with the Data Privacy Act of 2012 (Republic Act No. 10173) and its Implementing Rules and Regulations. This policy explains what personal data is collected, where it is collected and stored, how it is used and protected, and the rights of data subjects.","sections":[{"heading":"1. Information We Collect","body":"Student personal information (full name, LRN, birthdate, sex, address, guardian details, health and 4Ps information where applicable) and academic records (enrollment history, grades, school forms). Employee information (name, email, role, employee ID, designation, date hired) and system usage data (login timestamps, audit records)."},{"heading":"2. Where Data Is Collected and Stored","body":"Data is entered into the portal by authorized school personnel through official enrollment and encoding workflows. It is stored in the school''s centralized database on secured, access-controlled infrastructure with scheduled encrypted backups. Printed and exported records must be secured in school facilities."},{"heading":"3. How Your Data Is Used","body":"Personal data is processed for enrollment management, academic record-keeping, grade encoding and reporting, generation of school forms (SF1, SF5, SF9, SF10), reporting to the Department of Education, and the academic welfare of learners."},{"heading":"4. Data Security","body":"The school applies role-based access control (RBAC), least-privilege permissions, encrypted authentication (bcrypt password hashing and JWT sessions), full audit logging, upload restrictions, and scheduled encrypted database backups to protect personal data against unauthorized access, alteration, or disclosure."},{"heading":"5. Data Retention","body":"Records are retained in accordance with DepEd retention policies. Data no longer necessary for its purpose is disposed of securely following National Privacy Commission (NPC) guidelines."},{"heading":"6. Rights of Data Subjects","body":"Under RA 10173, data subjects have the right to access, correct, object to, and request processing restrictions on their personal data. Inquiries may be directed to the school''s designated Data Protection Officer."}]}',
    conditions_text = '{"intro":"The following conditions govern day-to-day use of the Hi5 Portal by all school personnel and authorized users.","sections":[{"heading":"1. Role-Based Access","body":"Access to modules and data is limited to what your role (Administrator, Teacher, Registrar, or Principal) requires. You must not attempt to circumvent, probe, or disable the system''s access controls."},{"heading":"2. Accuracy of Records","body":"Users encoding grades, enrollment data, or documents must verify their accuracy before submission. Corrections after submission must follow the official grade correction and records workflow."},{"heading":"3. Confidentiality","body":"Student records viewed within the portal are confidential. Exported files and printed school forms must be handled, stored, and disposed of in accordance with the school''s data privacy policy."},{"heading":"4. Audit and Monitoring","body":"All significant actions within the portal are logged for accountability and security. By using the system you consent to this logging for legitimate school purposes."},{"heading":"5. Termination of Access","body":"Access may be suspended or revoked upon separation from the school, violation of these conditions, or upon directive of the School Administrator."}]}'
WHERE id = 1;
